"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["6186"],{61344(e){e.exports=JSON.parse('{"id":"FIN-562","slug":"capitalization","term":"Capitalization","also_known_as":[],"difficulty":"Intermediate","definition":"Capitalization, in accounting, is the practice of recording a cost as an asset on the balance sheet rather than as an immediate expense, because it will benefit the business over more than one period.","explanation":["When a business spends money, it must decide whether the spending is an expense that relates only to the current period or an investment that will provide benefits for years. If it is the latter, the cost is capitalized: recorded as an asset and then gradually charged to the income statement through depreciation or amortization.","For example, a company that spends 120,000 on a new machine expected to last ten years capitalizes the 120,000, then records depreciation of about 12,000 a year. By contrast, 2,000 spent on routine repairs is expensed immediately, because it maintains the asset rather than improving it.","Costs commonly capitalized include equipment, buildings, major improvements, certain software development and, under some rules, interest on money borrowed to build an asset.","Capitalization decisions affect reported profit. Capitalizing a cost raises current profit, because the full cost is not expensed at once. This makes capitalization policies an area that auditors and analysts watch closely.","This meaning is different from market capitalization, which is the total market value of a company\'s shares."],"note":"","total":1500,"prev":{"slug":"capital-structure","term":"Capital Structure"},"next":{"slug":"captive-insurer","term":"Captive Insurer"}}')}}]);